PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?catchment
WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    {
      SELECT ?targetCatchment (SUM(xsd:decimal(?precipitation)) AS ?totalPrecipitation)
      WHERE {
        ?obs sosa:hasFeatureOfInterest ?targetCatchment ;
             sosa:observedProperty envthes:21299 ;
             sosa:resultTime ?time .
        OPTIONAL { ?obs sosa:hasSimpleResult ?simpleResult . }
        OPTIONAL {
          ?obs sosa:hasResult ?result .
          ?result qudt:numericValue ?numericResult .
        }
        BIND(COALESCE(?simpleResult, ?numericResult) AS ?precipitation)
        FILTER(BOUND(?precipitation))
        FILTER(STR(?time) >= "2012" && STR(?time) < "2016")
      }
      GROUP BY ?targetCatchment
      ORDER BY DESC(?totalPrecipitation)
      LIMIT 1
    }
    ?targetCatchment geo:hasGeometry ?targetGeometry .
    ?targetGeometry geo:asWKT ?targetWKT .
    ?catchment geo:hasGeometry ?geometry .
    ?geometry geo:asWKT ?wkt .
    FILTER(?catchment != ?targetCatchment)
    FILTER(geof:sfTouches(?wkt, ?targetWKT))
  }
}

